#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    std::vector<int> findSubstring(std::string s, std::vector<std::string>& words) {
        std::vector<int> result;
        if (s.empty() || words.empty()) {
            return result;
        }

        int word_len = words[0].length();
        int num_words = words.size();
        int total_len = word_len * num_words;

        if (s.length() < total_len) {
            return result;
        }

        // 1. Precompute target word counts
        std::unordered_map<std::string, int> target_word_counts;
        for (const std::string& word : words) {
            target_word_counts[word]++;
        }

        // 2. Iterate through all possible starting positions in s
        for (int i = 0; i <= (int)s.length() - total_len; ++i) {
            std::unordered_map<std::string, int> current_window_counts;
            bool valid = true;

            // 3. For each starting position, check if the substring is a valid concatenation
            for (int j = 0; j < num_words; ++j) {
                int word_start_index = i + j * word_len;
                std::string current_word = s.substr(word_start_index, word_len);

                // If the word is not in our target list, this substring is invalid
                if (target_word_counts.find(current_word) == target_word_counts.end()) {
                    valid = false;
                    break;
                }
                // Increment count for the current word in the window
                current_window_counts[current_word]++;

                // If the count of any word in the current window exceeds its target, this substring is invalid
                if (current_window_counts[current_word] > target_word_counts[current_word]) {
                    valid = false;
                    break;
                }
            }

            // 4. If all words were valid and their counts match, add to result
            if (valid && current_window_counts == target_word_counts) {
                result.push_back(i);
            }
        }

        return result;
    }
};

